using System.Threading.Tasks;using System.Windows.Threading;using System;using System.IO;using System.Reflection;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;
class Render{
 static void Pump(Task task){while(!task.IsCompleted){var frame=new DispatcherFrame();Dispatcher.CurrentDispatcher.BeginInvoke(DispatcherPriority.Background,new Action(()=>frame.Continue=false));Dispatcher.PushFrame(frame);System.Threading.Thread.Sleep(3);}task.GetAwaiter().GetResult();} static void Set(TV tv,string field,object value){typeof(TV).GetField(field,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(tv,value);}
 [STAThread]static int Main(){try{var app=new Application();System.Threading.SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());var tv=new TV();var inspect=typeof(TV).GetMethod("InspectApk",BindingFlags.Instance|BindingFlags.NonPublic);foreach(string apk in Directory.GetFiles(AppDomain.CurrentDomain.BaseDirectory+"apps","*.apk"))Pump((Task)inspect.Invoke(tv,new object[]{apk}));Set(tv,"serial","192.0.2.1:5555");Set(tv,"scannedFor","192.0.2.1:5555");Set(tv,"packages",new List<Package>{new Package{Name="系统界面",Id="com.android.systemui",Path="/system/priv-app/SystemUI/SystemUI.apk",State="已安装",Risk="保护",Group="保护组件",Reason="系统核心组件"},new Package{Name="电视视频 · 演示应用",Id="com.demo.video",Path="/data/app/com.demo.video/base.apk",State="已安装",Risk="推荐卸载",Group="深度精简",Reason="原版分类候选，仅用于界面验证"},new Package{Name="原厂电视桌面",Id="com.vendor.tvhome",Path="/system/app/TVHome/TVHome.apk",State="已安装",Risk="保护",Group="系统桌面",Reason="需先验证替代桌面",System=true,IsLauncher=true},new Package{Name="可恢复的系统应用",Id="com.vendor.optional",Path="/system/app/Optional/Optional.apk",State="已卸载",Risk="谨慎卸载",Group="普通精简",Reason="系统分区 APK 仍在"}});var status=(TextBlock)typeof(TV).GetField("status",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(tv);status.Text="● 界面演示 · 模拟电视数据";
 typeof(TV).GetMethod("ReadImportFolder",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(tv,new object[]{AppDomain.CurrentDomain.BaseDirectory});var show=typeof(TV).GetMethod("Show",BindingFlags.Instance|BindingFlags.NonPublic);foreach(string page in new[]{"投屏工作台","步骤1","步骤2","步骤3","步骤4","恢复列表","重新再来","安装与桌面","文件管理","配置与保护","设备工具"}){show.Invoke(tv,new object[]{page});var content=(FrameworkElement)tv.Content;content.Measure(new Size(1420,920));content.Arrange(new Rect(0,0,1420,920));content.UpdateLayout();var bmp=new RenderTargetBitmap(1420,920,96,96,PixelFormats.Pbgra32);bmp.Render(content);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bmp));using(var f=File.Create("preview-"+page+".png"))png.Save(f);}File.WriteAllText("render.log","11 pages rendered with fixture data; no live video captured");return 0;}catch(Exception ex){File.WriteAllText("render.log",ex.ToString());return 1;}}
}




